import { Router } from "express";
import { timeSlotController } from "./timeSlot.controller";
import { createTimeSlotValidationSchema, updateTimeSlotValidationSchema, } from "./timeSlot.validation";
import { checkAuth } from "../../middleware/checkAuth";
import { validateRequest } from "../../middleware/validateRequest";
import { Role } from "../../../generated/prisma/enums";
const router = Router();
router.post("/", checkAuth(Role.ADMIN, Role.SUPER_ADMIN), validateRequest(createTimeSlotValidationSchema), timeSlotController.createTimeSlot);
router.get("/", timeSlotController.getAllTimeSlots);
router.get("/:timeSlotId", timeSlotController.getTimeSlotById);
router.patch("/:timeSlotId", checkAuth(Role.ADMIN, Role.SUPER_ADMIN), validateRequest(updateTimeSlotValidationSchema), timeSlotController.updateTimeSlot);
router.delete("/:timeSlotId", checkAuth(Role.ADMIN, Role.SUPER_ADMIN), timeSlotController.deleteTimeSlot);
export const timeSlotRoutes = router;
